-- Seed controlled MRC Forms 2-7 as non-RAG repository templates.
do $$
declare
  item record;
begin
  for item in select * from (values
    ('MRC Form 2 Template','MRC_FORM_2','1','portrait','2024-08-01',$html$<html><head><style>@page{size:8.5in 11in;margin:14mm}body{font:11pt Arial;margin:0}.page{min-height:9.8in}.header,.signatures{display:flex;justify-content:space-between}.meta{font-size:9pt}.title{text-align:center;font-weight:bold;margin:28px}.field{margin:10px 0;border-bottom:1px solid #000;padding:4px}.attendance,.agenda{margin:16px 0}.line{display:inline-block;border-bottom:1px solid #000;min-width:180px}.inputs{font-size:9pt}.signatures{margin-top:28px}.signature{width:42%;text-align:center;border-top:1px solid #000;padding-top:4px}@media print{.page{break-after:auto}}</style></head><body><div class="page"><div class="header"><b>CEBU TECHNOLOGICAL UNIVERSITY</b><span class="meta">MRC Form 2<br>August 1, 2024<br>Revision: 1</span></div><div class="title">MANAGEMENT REVIEW MEETING MINUTES</div><div class="field">No: [NO]</div><div class="field">Date: [DATE]</div><div class="field">Time Started: [TIME_STARTED]</div><div class="field">Time Adjourned: [TIME_ADJOURNED]</div><div class="attendance">Attendance:<br>[ATTENDANCE_1]<br>[ATTENDANCE_2]<br>[ATTENDANCE_3]<br>[ATTENDANCE_4]<br>[ATTENDANCE_5]<br>[ATTENDANCE_6]<br>[ATTENDANCE_7]<br>[ATTENDANCE_8]<br>[ATTENDANCE_9]</div><div class="agenda">Agenda: [AGENDA_1]<br>[AGENDA_2]<br>[AGENDA_3]<br>[AGENDA_4]</div><div class="inputs"><b>Mandatory review inputs:</b> previous actions; relevant internal and external changes; QMS performance and effectiveness; customer feedback; objectives; process and service conformity; corrective actions; monitoring; audit results; external providers; resources; risks and opportunities; and improvement opportunities.</div><div class="signatures"><div class="signature">[RECORDED_BY_NAME]<br>Recorded by</div><div class="signature">[NOTED_BY_NAME]<br>Noted by</div></div></div></body></html>$html$),
    ('MRC Form 3 Template','MRC_FORM_3','0','landscape','2012-10-01',$html$<html><head><style>@page{size:11in 8.5in;margin:10mm}body{font:8pt Arial;margin:0}.header,.footer{display:flex;justify-content:space-between}.title{text-align:center;font-weight:bold;margin:15px}table{width:100%;border-collapse:collapse;table-layout:fixed}thead{display:table-header-group}th,td{border:1px solid #000;padding:5px;vertical-align:top}tr{break-inside:avoid}.footer{margin-top:22px}.sig{text-align:center;min-width:140px;border-top:1px solid #000;padding-top:3px}</style></head><body><div class="header"><b>CEBU TECHNOLOGICAL UNIVERSITY</b><span>MRC Form 3<br>October 2012<br>Revision: 0</span></div><div class="title">SHORT, MEDIUM, AND LONG TERM PLAN<br>([YEAR_1], [YEAR_2], [YEAR_3])</div><table><thead><tr><th>FUNCTION AREAS</th><th>OBJECTIVE</th><th>KRA</th><th>SHORT TERM</th><th>KRA</th><th>MEDIUM TERM</th><th>KRA</th><th>LONG TERM</th></tr></thead><tbody>[LOGSHEET_ROWS]</tbody></table><div class="footer"><div class="sig">[PREPARED_BY]<br>Prepared by</div><div>[VP_ADMIN] · [VP_RD] · [VP_ACAD] · [VP_PEBA]<br>Recommending Approval</div><div class="sig">[APPROVED_BY]<br>Approved by</div></div></body></html>$html$),
    ('MRC Form 4 Template','MRC_FORM_4','0','landscape','2012-10-01',$html$<html><head><style>@page{size:11in 8.5in;margin:10mm}body{font:8pt Arial;margin:0}.header,.footer{display:flex;justify-content:space-between}.title{text-align:center;font-weight:bold;margin:15px}table{width:100%;border-collapse:collapse;table-layout:fixed}thead{display:table-header-group}th,td{border:1px solid #000;padding:4px;vertical-align:top}tr{break-inside:avoid}.footer{margin-top:22px}.sig{text-align:center;min-width:140px;border-top:1px solid #000;padding-top:3px}</style></head><body><div class="header"><b>CEBU TECHNOLOGICAL UNIVERSITY</b><span>MRC Form 4<br>October 2012<br>Revision: 0</span></div><div class="title">ANNUAL PLAN<br>CY [YEAR]</div><table><thead><tr><th>FUNCTION/AREA</th><th>OBJECTIVES</th><th>STRATEGIES</th><th>TIME FRAME</th><th>PERSONS INVOLVED</th><th>BUDGET</th><th>EXPECTED OUTPUT</th><th>ACTUAL ACCOMPLISHMENT</th><th>REMARKS</th></tr></thead><tbody>[LOGSHEET_ROWS]</tbody></table><div class="footer"><div class="sig">[PREPARED_BY]<br>Prepared by</div><div>[VP_ADMIN] · [VP_RD] · [VP_ACAD] · [VP_PEBA]<br>Recommending Approval</div><div class="sig">[APPROVED_BY]<br>Approved by</div></div></body></html>$html$),
    ('MRC Form 5 Template','MRC_FORM_5','0','landscape','2021-03-01',$html$<html><head><style>@page{size:11in 8.5in;margin:10mm}body{font:8pt Arial;margin:0}.header,.footer{display:flex;justify-content:space-between}.title{text-align:center;font-weight:bold;margin:15px}table{width:100%;border-collapse:collapse;table-layout:fixed}thead{display:table-header-group}th,td{border:1px solid #000;padding:4px;vertical-align:top}tr{break-inside:avoid}.footer{margin-top:24px}.sig{text-align:center;width:30%;border-top:1px solid #000;padding-top:3px}</style></head><body><div class="header"><b>CEBU TECHNOLOGICAL UNIVERSITY</b><span>MRC Form 5<br>March 2021<br>Revision: 0</span></div><div class="title">RISK IDENTIFICATION<br>[UNIT_NAME]</div><p><b>OBJECTIVE:</b> [OBJECTIVE_TEXT]</p><table><thead><tr><th>ISSUES</th><th>RISKS</th><th>IMPACT</th><th>LIKELIHOOD</th><th>RISK FACTOR</th><th>RISK CONTROL/ACTION</th><th>TARGET DATE</th><th>PERSON/S RESPONSIBLE</th><th>ASSESSMENT DATE</th><th>COMPLETION DATE</th></tr></thead><tbody>[LOGSHEET_ROWS]</tbody></table><div class="footer"><div class="sig">[PREPARED_BY]<br>Prepared by</div><div class="sig">[REVIEWED_BY]<br>Reviewed by</div><div class="sig">[APPROVED_BY]<br>Approved by</div></div></body></html>$html$),
    ('MRC Form 6 Template','MRC_FORM_6','0','landscape','2021-03-01',$html$<html><head><style>@page{size:11in 8.5in;margin:10mm}body{font:8pt Arial;margin:0}.header,.footer{display:flex;justify-content:space-between}.title{text-align:center;font-weight:bold;margin:15px}table{width:100%;border-collapse:collapse;table-layout:fixed}thead{display:table-header-group}th,td{border:1px solid #000;padding:5px;vertical-align:top}tr{break-inside:avoid}.footer{margin-top:24px}.sig{text-align:center;width:30%;border-top:1px solid #000;padding-top:3px}</style></head><body><div class="header"><b>CEBU TECHNOLOGICAL UNIVERSITY</b><span>MRC Form 6<br>March 2021<br>Revision: 0</span></div><div class="title">OPPORTUNITIES IDENTIFICATION<br>[UNIT_NAME]</div><table><thead><tr><th>OPPORTUNITY</th><th>ACTION PLAN</th><th>TARGET DATE</th><th>PERSON/S RESPONSIBLE</th><th>ASSESSMENT DATE</th><th>COMPLETION DATE</th></tr></thead><tbody>[LOGSHEET_ROWS]</tbody></table><div class="footer"><div class="sig">[PREPARED_BY]<br>Prepared by</div><div class="sig">[REVIEWED_BY]<br>Reviewed by</div><div class="sig">[APPROVED_BY]<br>Approved by</div></div></body></html>$html$),
    ('MRC Form 7 Template','MRC_FORM_7','0','landscape','2021-03-01',$html$<html><head><style>@page{size:11in 8.5in;margin:10mm}body{font:8pt Arial;margin:0}.header,.footer{display:flex;justify-content:space-between}.title{text-align:center;font-weight:bold;margin:20px}table{width:100%;border-collapse:collapse;table-layout:fixed}thead{display:table-header-group}th,td{border:1px solid #000;padding:5px;vertical-align:top}tr{break-inside:avoid}.footer{margin-top:28px}.sig{text-align:center;width:35%;border-top:1px solid #000;padding-top:3px}</style></head><body><div class="header"><b>CEBU TECHNOLOGICAL UNIVERSITY</b><span>MRC Form 7<br>March 2021<br>Revision: 0</span></div><div class="title">RELEVANT ISSUES LOG</div><table><thead><tr><th>INTERESTED PARTIES</th><th>INTERNAL/EXTERNAL</th><th>REASONS FOR INCLUSION</th><th>ISSUES OF CONCERN</th><th>PROCESSES AFFECTED</th><th>PRIORITY</th><th>TREATMENT METHOD</th><th>RECORDS/NOTES</th></tr></thead><tbody>[LOGSHEET_ROWS]</tbody></table><div class="footer"><div class="sig">[PREPARED_BY]<br>Quality Assurance Chair/Head</div><div class="sig">[APPROVED_BY]<br>Campus Director</div></div></body></html>$html$)
  ) as templates(name, code, revision, orientation, effectivity_date, html)
  loop
    insert into public.document_sections (content, metadata, embedding)
    select '', jsonb_build_object(
      'name', item.name, 'category', 'Forms / Templates', 'office', 'Quality Assurance Office',
      'program', 'GLOBAL', 'version', '1.0', 'effectivity_date', item.effectivity_date,
      'status', 'Active', 'scope_type', 'CAMPUS', 'scope_code', 'ARGAO',
      'template_code', item.code, 'template_revision', item.revision,
      'page_size', 'short', 'orientation', item.orientation,
      'original_filename', item.name || '.html', 'content_html', item.html
    ), null
    where not exists (
      select 1 from public.document_sections
      where metadata->>'name' = item.name and coalesce(metadata->>'status', 'Active') <> 'Archived'
    );
  end loop;
end $$;
